pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != address(0));
        // To ensure the caller is admin, we set the test contract as admin by deploying from this contract.
        // Since the admin is set in constructor as msg.sender, the test contract is admin.
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("setOwner(address)", _owner));
        assertTrue(success && c.owner() == _owner);
    }
}

