pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;
    function setUp() public { 
        c = new C(); 
        initialOwner = address(this);
    }
    function testFuzz_property(address newOwner) public {
        // Record the owner before the call
        address before = c.owner();

        // Call setOwner and capture revert status
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));

        // Read the owner after the call
        address after = c.owner();

        // General rule: if the call succeeded, owner equals newOwner; if it reverted, owner stays unchanged
        assertTrue((success && after == newOwner) || (!success && after == before));
    }
}

