import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;

    function setUp() public {
        c = new C();
        initialOwner = c.owner();
    }

    function testFuzz_property(address _newOwner) public {
        // Record the owner before the call
        address ownerBefore = c.owner();

        // Try to call setOwner; it will revert if admin check fails (i.e., always revert in mutant)
        (bool success, ) = address(c).call(abi.encodeCall(c.setOwner, (_newOwner)));

        address ownerAfter = c.owner();

        // General rule: if the call succeeded, owner must be the new owner;
        // if it reverted, owner must be unchanged.
        assertTrue(success ? (ownerAfter == _newOwner) : (ownerAfter == ownerBefore));
    }
}

